/**
 * @param {number[]} nums
 * @return {void}
 */
var ArrayWrapper = function(nums) {
    // Store the input array
    this.nums = nums;
};

/**
 * Used by the + operator: obj1 + obj2 becomes number + number
 * @return {number}
 */
ArrayWrapper.prototype.valueOf = function() {
    // Initial value 0 makes the empty array sum to 0
    return this.nums.reduce((sum, x) => sum + x, 0);
};

/**
 * Used by String(obj)
 * @return {string}
 */
ArrayWrapper.prototype.toString = function() {
    // Comma separated, wrapped in brackets, e.g. "[1,2,3]"
    return JSON.stringify(this.nums);
};
